为什么有这个东西，一方面时AOP框架的需要，另一方面是增加软件逆向的难度 动态生成类的技术目前大体上分为两类，一类是通过操作字节码框架如cglib&#x2F;Javassist去实现，另一类就是JNI方式，调用dll&#x2F;so库，内存中动态还原。这两种方式都能实现隐藏类 1. 看一个Javassist动态生成类的例子12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364656667686970717273package com.vvvtimes;import java.lang.reflect.Modifier;import javassist.ClassPool;import javassist.CtClass;import javassist.CtConstructor;import javassist.CtField;import javassist.CtMethod;import javassist.CtNewMethod;public class DynamicGenerateClass &#123; public static void main(String[] args) throws Exception &#123; // ClassPool：CtClass对象的容器 ClassPool pool = ClassPool.getDefault(); // 通过ClassPool生成一个public新类Employee.java CtClass ctClass = pool.makeClass(&quot;com.vvvtimes.bean.Employee&quot;); // 添加字段 // 首先添加字段private String ename CtField enameField = new CtField(pool.getCtClass(&quot;java.lang.String&quot;), &quot;ename&quot;, ctClass); enameField.setModifiers(Modifier.PRIVATE); ctClass.addField(enameField); // 其次添加字段privtae int eage CtField eageField = new CtField(pool.getCtClass(&quot;int&quot;), &quot;eage&quot;, ctClass); eageField.setModifiers(Modifier.PRIVATE); ctClass.addField(eageField); // 其次添加字段privtae int eage CtField esexField = new CtField(pool.getCtClass(&quot;int&quot;), &quot;esex&quot;, ctClass); esexField.setModifiers(Modifier.PRIVATE); ctClass.addField(esexField); // 为字段ename和eno添加getter和setter方法 ctClass.addMethod(CtNewMethod.getter(&quot;getEname&quot;, enameField)); ctClass.addMethod(CtNewMethod.setter(&quot;setEname&quot;, enameField)); ctClass.addMethod(CtNewMethod.getter(&quot;getEage&quot;, eageField)); ctClass.addMethod(CtNewMethod.setter(&quot;setEage&quot;, eageField)); ctClass.addMethod(CtNewMethod.getter(&quot;getSex&quot;, esexField)); ctClass.addMethod(CtNewMethod.setter(&quot;setSex&quot;, esexField)); // 添加构造函数 CtConstructor ctConstructor = new CtConstructor(new CtClass[] &#123;&#125;, ctClass); // 为构造函数设置函数体 StringBuffer buffer = new StringBuffer(); buffer.append(&quot;&#123;
&quot;).append(&quot;ename=\&quot;gsls200808\&quot;;
&quot;).append(&quot;eage=25;
&quot;).append(&quot;esex=1;
&#125;&quot;); ctConstructor.setBody(buffer.toString()); // 把构造函数添加到新的类中 ctClass.addConstructor(ctConstructor); // 添加自定义方法 CtMethod ctMethod = new CtMethod(CtClass.voidType, &quot;printInfo&quot;, new CtClass[] &#123;&#125;, ctClass); // 为自定义方法设置修饰符 ctMethod.setModifiers(Modifier.PUBLIC); // 为自定义方法设置函数体 StringBuffer buffer2 = new StringBuffer(); buffer2.append(&quot;&#123;
&quot;).append(&quot;System.out.println(\&quot;begin!\&quot;);
&quot;) .append(&quot;System.out.println(\&quot;name=\&quot;+ename);
&quot;).append(&quot;System.out.println(\&quot;age=\&quot;+eage);
&quot;) .append(&quot;System.out.println(\&quot;sex=\&quot;+esex);
&quot;).append(&quot;System.out.println(\&quot;end!\&quot;);
&quot;).append(&quot;&#125;&quot;); ctMethod.setBody(buffer2.toString()); ctClass.addMethod(ctMethod); // 为了验证效果，下面使用反射执行方法printInfo Class&lt;?&gt; clazz = ctClass.toClass(); Object obj = clazz.newInstance(); obj.getClass().getMethod(&quot;printInfo&quot;, new Class[] &#123;&#125;).invoke(obj, new Object[] &#123;&#125;); &#125;&#125; 需要引用的第三方jar：javassist-3.20.0-GA.jar 运行结果 12345begin!name=gsls200808age=25sex=1end! 代码的意思相当于在内存中创建了一个名为com.vvvtimes.bean.Employee的类，并通过反射方式调用了printInfo方法进行输出。 这个类的内容大致如下，只不过我们在上面是动态生成的 12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849package com.vvvtimes.bean;import java.io.PrintStream;public class Employee&#123; private String ename = &quot;gsls200808&quot;; private int eage = 25; private int esex = 1; public String getEname() &#123; return this.ename; &#125; public void setEname(String paramString) &#123; this.ename = paramString; &#125; public int getEage() &#123; return this.eage; &#125; public void setEage(int paramInt) &#123; this.eage = paramInt; &#125; public int getSex() &#123; return this.esex; &#125; public void setSex(int paramInt) &#123; this.esex = paramInt; &#125; public void printInfo() &#123; System.out.println(&quot;begin!&quot;); System.out.println(&quot;name=&quot; + this.ename); System.out.println(&quot;age=&quot; + this.eage); System.out.println(&quot;sex=&quot; + this.esex); System.out.println(&quot;end!&quot;); &#125;&#125; 在后续文章中我们会讲如何获取内存中的类
